    if (size < 8u) {
        return (-EINVAL);
    }

    dst_p->analog_voltage = unpack_right_shift_u16(src_p[0], 0u, 0xffu);
    dst_p->analog_voltage |= unpack_left_shift_u16(src_p[1], 8u, 0x03u);
    analog_velocity = unpack_right_shift_u32(src_p[1], 2u, 0xfcu);
    analog_velocity |= unpack_left_shift_u32(src_p[2], 6u, 0xffu);
    analog_velocity |= unpack_left_shift_u32(src_p[3], 14u, 0xffu);

    if ((analog_velocity & (1u << 21)) != 0u) {
        analog_velocity |= 0xffc00000u;
    }

    dst_p->analog_velocity = (int32_t)analog_velocity;
    analog_position = unpack_right_shift_u32(src_p[4], 0u, 0xffu);
    analog_position |= unpack_left_shift_u32(src_p[5], 8u, 0xffu);
    analog_position |= unpack_left_shift_u32(src_p[6], 16u, 0xffu);
    analog_position |= unpack_left_shift_u32(src_p[7], 24u, 0xffu);
